package org.freecad.mobilelab;
import java.io.*;import java.util.*;
/** Explicit planar boundary-hole repair. Produces a new mesh, with strict mobile bounds. */
final class PlanarMeshRepair {
 static final class Key{final long x,y,z;Key(float[] p,double t){x=Math.round(p[0]/t);y=Math.round(p[1]/t);z=Math.round(p[2]/t);}public int hashCode(){return Objects.hash(x,y,z);}public boolean equals(Object o){if(!(o instanceof Key))return false;Key k=(Key)o;return x==k.x&&y==k.y&&z==k.z;}}
 static final class Edge{final int a,b;int uses=1;Edge(int a,int b){this.a=a;this.b=b;}}
 static double cross(double[] a,double[] b,double[] c){return (b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);}
 static boolean inside(double[] p,double[] a,double[] b,double[] c,double orientation){return cross(a,b,p)*orientation>=-1e-10&&cross(b,c,p)*orientation>=-1e-10&&cross(c,a,p)*orientation>=-1e-10;}
 static ArrayList<int[]> cap(List<Integer> loop,List<float[]> points,double tolerance)throws IOException{
  if(loop.size()<3||loop.size()>128)throw new IOException("Planar hole must have 3 to 128 boundary vertices");Collections.reverse(loop);float[] origin=points.get(loop.get(0));double[] normal=new double[3];double length=0;for(int i=1;i+1<loop.size()&&length<1e-12;i++){float[] a=points.get(loop.get(i)),b=points.get(loop.get(i+1));double x=a[0]-origin[0],y=a[1]-origin[1],z=a[2]-origin[2],u=b[0]-origin[0],v=b[1]-origin[1],w=b[2]-origin[2];normal=new double[]{y*w-z*v,z*u-x*w,x*v-y*u};length=Math.sqrt(normal[0]*normal[0]+normal[1]*normal[1]+normal[2]*normal[2]);}if(length<1e-12)throw new IOException("Degenerate boundary loop");for(int i=0;i<3;i++)normal[i]/=length;int drop=Math.abs(normal[0])>Math.abs(normal[1])?(Math.abs(normal[0])>Math.abs(normal[2])?0:2):(Math.abs(normal[1])>Math.abs(normal[2])?1:2);Map<Integer,double[]> projected=new HashMap<>();for(int id:loop){float[] p=points.get(id);double plane=0;for(int i=0;i<3;i++)plane+=(p[i]-origin[i])*normal[i];if(Math.abs(plane)>tolerance*2)throw new IOException("Boundary is not planar within welding tolerance");projected.put(id,new double[]{p[(drop+1)%3],p[(drop+2)%3]});}
  for(int i=0;i<loop.size();i++)for(int j=i+2;j<loop.size();j++){if(i==0&&j==loop.size()-1)continue;double[] a=projected.get(loop.get(i)),b=projected.get(loop.get((i+1)%loop.size())),c=projected.get(loop.get(j)),d=projected.get(loop.get((j+1)%loop.size()));if(cross(a,b,c)*cross(a,b,d)<0&&cross(c,d,a)*cross(c,d,b)<0)throw new IOException("Boundary loop self-intersects");}
  double area=0;for(int i=0;i<loop.size();i++){double[] a=projected.get(loop.get(i)),b=projected.get(loop.get((i+1)%loop.size()));area+=a[0]*b[1]-a[1]*b[0];}if(Math.abs(area)<1e-10)throw new IOException("Boundary loop has no planar area");double sign=Math.signum(area);ArrayList<Integer> remaining=new ArrayList<>(loop);ArrayList<int[]> triangles=new ArrayList<>();while(remaining.size()>3){boolean made=false;for(int i=0;i<remaining.size();i++){int a=remaining.get((i+remaining.size()-1)%remaining.size()),b=remaining.get(i),c=remaining.get((i+1)%remaining.size());double[] pa=projected.get(a),pb=projected.get(b),pc=projected.get(c);if(cross(pa,pb,pc)*sign<=1e-10)continue;boolean blocked=false;for(int id:remaining)if(id!=a&&id!=b&&id!=c&&inside(projected.get(id),pa,pb,pc,sign)){blocked=true;break;}if(!blocked){triangles.add(new int[]{a,b,c});remaining.remove(i);made=true;break;}}if(!made)throw new IOException("Boundary cannot be triangulated safely");}triangles.add(new int[]{remaining.get(0),remaining.get(1),remaining.get(2)});return triangles;
 }
 static int fill(File source,File target,double tolerance)throws Exception{
  if(!Double.isFinite(tolerance)||tolerance<1e-6||tolerance>.01)throw new IOException("Welding tolerance must be .000001 to .01 mm");Map<Key,Integer> vertices=new HashMap<>();ArrayList<float[]> points=new ArrayList<>();Map<Long,Edge> edges=new LinkedHashMap<>();ArrayList<int[]> triangles=new ArrayList<>();try(RandomAccessFile f=new RandomAccessFile(source,"r")){int count=MeshFormats.count(f,100000);for(int i=0;i<count;i++){float[] p=MeshFormats.triangle(f,i);int[] tri=new int[3];for(int j=0;j<3;j++){float[] point=Arrays.copyOfRange(p,j*3,j*3+3);Key k=new Key(point,tolerance);Integer id=vertices.get(k);if(id==null){id=points.size();vertices.put(k,id);points.add(point);}tri[j]=id;}if(tri[0]==tri[1]||tri[1]==tri[2]||tri[2]==tri[0])throw new IOException("Degenerate triangles must be repaired first");triangles.add(tri);for(int j=0;j<3;j++){int a=tri[j],b=tri[(j+1)%3];long key=((long)Math.min(a,b)<<32)|Math.max(a,b);Edge edge=edges.get(key);if(edge==null)edges.put(key,new Edge(a,b));else{if(++edge.uses>2)throw new IOException("Non-manifold edges require manual repair");if(edge.a==a)throw new IOException("Repair inconsistent triangle winding before filling holes");}}}}
  Map<Integer,Integer> next=new LinkedHashMap<>();Set<Integer> incoming=new HashSet<>();for(Edge e:edges.values())if(e.uses==1){if(next.put(e.a,e.b)!=null||!incoming.add(e.b))throw new IOException("Branched boundary cannot be filled safely");}if(next.isEmpty())throw new IOException("Mesh has no open boundary loops");if(next.size()>512)throw new IOException("Hole repair exceeds 512 boundary edges");if(!next.keySet().equals(incoming))throw new IOException("Open boundary chains require manual repair");int holes=0;while(!next.isEmpty()){int start=next.keySet().iterator().next(),id=start;ArrayList<Integer> loop=new ArrayList<>();do{loop.add(id);Integer n=next.remove(id);if(n==null)throw new IOException("Invalid boundary loop");id=n;}while(id!=start);triangles.addAll(cap(loop,points,tolerance));holes++;}try(DataOutputStream out=new DataOutputStream(new BufferedOutputStream(new FileOutputStream(target)))){MeshFormats.stlHeader(out,triangles.size());for(int[] tri:triangles){float[] p=new float[9];for(int j=0;j<3;j++)System.arraycopy(points.get(tri[j]),0,p,j*3,3);MeshFormats.stlTriangle(out,p);}}return holes;
 }
}
